class Counter {
private:
    int count;
public:
    Counter(int count) {
        // 'this->count' refers to data member, 'count' is the parameter
        this->count = count;
    }

    Counter& increment() {
        this->count++;
        return *this; // Returns current object for chaining
    }

    void display() {
        cout << "Count: " << this->count << endl;
    }
};

int main() {
    Counter c(5);
    c.increment().increment();
    c.display();
    return 0;
}

