#include <iostream>
using namespace std;

class Deep {
public:
    int* data;
    Deep(int val) {
        data = new int(val);
    }
    // Deep copy constructor
    Deep(const Deep& source) {
        data = new int(*(source.data)); // Allocating new memory
    }
    ~Deep() {
        delete data;
    }
};

int main() {
    Deep obj1(10);
    Deep obj2 = obj1; // Invokes deep copy constructor
    *(obj2.data) = 20;
    cout << "obj1: " << *(obj1.data) << endl; // Remains 10
    cout << "obj2: " << *(obj2.data) << endl; // Becomes 20
    return 0;
}

