code.src:
#include <iostream>
using namespace std;

// 1. Compile-Time Polymorphism (Function Overloading)
class Printer {
public:
    void print(int i) {
        cout << "Printing int: " << i << endl;
    }
    void print(string s) {
        cout << "Printing string: " << s << endl;
    }
};

// 2. Run-Time Polymorphism (Virtual Functions)
class Base {
public:
    virtual void show() {
        cout << "Base class show()\n";
    }
};

class Derived : public Base {
public:
    void show() override {
        cout << "Derived class show()\n";
    }
};

int main() {
    // Compile-time demonstration
    Printer p;
    p.print(10);
    p.print("Hello");

    // Run-time demonstration
    Base* b = new Derived();
    b->show(); // Resolved at runtime!
    delete b;
    return 0;
}

#include <iostream>

class Shape {
public:
    virtual double area() const = 0; // pure virtual, makes Shape abstract
    virtual ~Shape() = default;      // ensure proper cleanup
};

class Circle : public Shape {
    double r;
public:
    Circle(double radius): r(radius) {}
    double area() const override { return 3.14159 * r * r; } // overrides Shape::area
};

class Square : public Shape {
    double side;
public:
    Square(double s): side(s) {}
    double area() const override { return side * side; }
};

int main(){
    Shape* s1 = new Circle(2.0);
    Shape* s2 = new Square(3.0);
    std::cout << "Circle area: " << s1->area() << '\n'; // dynamic dispatch via vtable
    std::cout << "Square area: " << s2->area() << '\n';
    delete s1; delete s2; // calls derived destructors because ~Shape is virtual
    return 0;
}

