// Base contract
class Account {
public:
    virtual void deposit(double amount) = 0;
    virtual void withdraw(double amount) = 0;
    virtual ~Account() = default;
};

class SavingsAccount : public Account {
private:
    double balance = 0;
public:
    void deposit(double amount) override {
        balance += amount;
        std::cout << "Deposited: " << amount << std::endl;
    }
    void withdraw(double amount) override {
        if (balance >= amount) {
            balance -= amount;
            std::cout << "Withdrew: " << amount << std::endl;
        } else {
            std::cout << "Insufficient funds!\n";
        }
    }
};

// LSP Compliant: Checking account honors the Account contract fully
class CheckingAccount : public Account {
private:
    double balance = 0;
public:
    void deposit(double amount) override {
        balance += amount;
        std::cout << "Checking Deposited: " << amount << std::endl;
    }
    void withdraw(double amount) override {
        balance -= amount; // Allows overdraft
        std::cout << "Checking Withdrew (with overdraft): " << amount << std::endl;
    }
};

void performBankOperations(Account& acc) {
    acc.deposit(1000.0);
    acc.withdraw(500.0);
}

int main() {
    SavingsAccount savings;
    CheckingAccount checking;

    performBankOperations(savings);  // Works correctly
    performBankOperations(checking); // Works correctly, respects LSP
