#include <bits/stdc++.h>
using namespace std;

// Strategy interface
class SortStrategy {
public:
    virtual void sort(vector<int>& data) = 0;
    virtual ~SortStrategy() = default;
};

// Concrete strategy 1: Bubble Sort
class BubbleSort : public SortStrategy {
public:
    void sort(vector<int>& data) override {
        for (size_t i = 0; i < data.size(); ++i)
            for (size_t j = 0; j < data.size() - i - 1; ++j)
                if (data[j] > data[j+1]) swap(data[j], data[j+1]);
    }
};

// Concrete strategy 2: Quick Sort
class QuickSort : public SortStrategy {
    void quick(vector<int>& a, int l, int r){
        int i=l, j=r, pivot=a[(l+r)/2];
        while(i<=j){
            while(a[i]<pivot) i++; while(a[j]>pivot) j--;
            if(i<=j){ swap(a[i],a[j]); i++; j--; }
        }
        if(l<j) quick(a,l,j);
        if(i<r) quick(a,i,r);
    }
public:
    void sort(vector<int>& data) override { if(!data.empty()) quick(data,0,data.size()-1); }
};

// Context that uses a strategy
class SortContext {
    SortStrategy* strategy; // owned elsewhere or use smart pointer
public:
    explicit SortContext(SortStrategy* s=nullptr): strategy(s) {}
    void setStrategy(SortStrategy* s){ strategy = s; }
    void sortData(vector<int>& d){ if(strategy) strategy->sort(d); }
};

int main(){
    vector<int> arr = {5,2,9,1,5,6};
    SortContext ctx(new BubbleSort()); // use bubble sort
    ctx.sortData(arr);
    for(int x:arr) cout<<x<<" "; // 1 2 5 5 6 9
    cout<<"\n";
    ctx.setStrategy(new QuickSort()); // switch at runtime
    arr = {3,8,2,7,4};
    ctx.sortData(arr);
    for(int x:arr) cout<<x<<" "; // 2 3 4 7 8
    return 0;
}

