};

class CompositeGraphic : public Graphic {
    vector<Graphic*> children;
public:
    void add(Graphic* g) { children.push_back(g); }
    void draw() override {
        for (auto g : children) g->draw(); // Recursive delegation
    }
};

int main() {
    CompositeGraphic root;
    root.add(new Dot());
    CompositeGraphic sub;
    sub.add(new Dot());
    root.add(&sub);
    root.draw();
    return 0;
}

