class BulletType {
    std::string color;
    double damage;
public:
    BulletType(std::string c, double d) : color(c), damage(d) {}
    void display(int x, int y) const {
        // x, y are extrinsic state passed in
        std::cout << "Bullet [Color: " << color << ", Dmg: " << damage 
                  << "] at coords (" << x << ", " << y << ")\n";
    }
};

// Flyweight Factory
class BulletFactory {
    std::unordered_map<std::string, std::shared_ptr<BulletType>> cache;
public:
    std::shared_ptr<BulletType> getBulletType(std::string color, double damage) {
        std::string key = color + std::to_string(damage);
        if (cache.find(key) == cache.end()) {
            cache[key] = std::make_shared<BulletType>(color, damage);
        }
        return cache[key];
    }
};

int main() {
    BulletFactory factory;
    // Millions of bullets share the same intrinsic type objects
    auto b1 = factory.getBulletType("Red", 15.5);
    b1->display(10, 20); // Extrinsic: 10, 20
    auto b2 = factory.getBulletType("Red", 15.5);
    b2->display(50, 60); // Extrinsic: 50, 60
    return 0;
}

