#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

class IObserver {
public:
    virtual ~IObserver() = default;
    virtual void update(const std::string& message) = 0;
};

class Subscriber : public IObserver {
    std::string name;
public:
    Subscriber(std::string n) : name(n) {}
    void update(const std::string& message) override {
        std::cout << name << " received notification: " << message << "\n";
    }
};

class Channel {
    std::vector<IObserver*> observers;
    std::string latestVideo;
public:
    void attach(IObserver* obs) {
        observers.push_back(obs);
    }
    void detach(IObserver* obs) {
        observers.erase(std::remove(observers.begin(), observers.end(), obs), observers.end());
    }
    void notify() {
        for (IObserver* obs : observers) {
            obs->update(latestVideo);
        }
    }
    void uploadVideo(const std::string& title) {
        latestVideo = title;
        notify();
    }
};

int main() {
    Channel channel;
    Subscriber s1("Alice");
    Subscriber s2("Bob");

    channel.attach(&s1);
    channel.attach(&s2);

    channel.uploadVideo("Design Patterns in C++");
    return 0;
}

