template <typename T>
class Iterator {
public:
    virtual ~Iterator() = default;
    virtual bool hasNext() = 0;
    virtual T next() = 0;
};

template <typename T>
class VectorIterator : public Iterator<T> {
    const std::vector<T>& collection;
    size_t index = 0;
public:
    VectorIterator(const std::vector<T>& c) : collection(c) {}
    bool hasNext() override { return index < collection.size(); }
    T next() override { return collection[index++]; }
};

int main() {
    std::vector<int> vec = {10, 20, 30};
    VectorIterator<int> it(vec);
    while (it.hasNext()) {
        std::cout << it.next() << " ";
    }
    return 0;
}

#include <iostream>
#include <stack>
#include <memory>

// ---------- Memento ----------
class Memento {
    friend class Originator;               // only Originator can access
private:
    int state;                            // snapshot of Originator's state
    explicit Memento(int s) : state(s) {} // private ctor
};

// ---------- Originator ----------
class Originator {
    int state = 0;
public:
    void setState(int s) { state = s; }
    int getState() const { return state; }
    // Create a snapshot
    std::unique_ptr<Memento> save() const {
        return std::make_unique<Memento>(state);
    }
    // Restore from a snapshot
    void restore(const Memento& m) {
        state = m.state;
    }
};

// ---------- Caretaker ----------
class Caretaker {
    std::stack<std::unique_ptr<Memento>> history;
public:
    void backup(const Originator& o) {
        history.push(o.save());
    }
    void undo(Originator& o) {
        if (!history.empty()) {
            o.restore(*history.top());
            history.pop();
        }
    }
};

int main() {
    Originator obj;  // starts with state 0
    Caretaker mgr;

    obj.setState(10);
    mgr.backup(obj);          // save 10
    obj.setState(20);
    mgr.backup(obj);          // save 20
    obj.setState(30);
    std::cout << "Current: " << obj.getState() << "\n"; // 30

    mgr.undo(obj);            // revert to 20
    std::cout << "After undo: " << obj.getState() << "\n"; // 20
    mgr.undo(obj);            // revert to 10
    std::cout << "After second undo: " << obj.getState() << "\n"; // 10
    return 0;
}

coding:
// Solution sketch:
// - TextEditor (Originator) holds a std::string buffer.
// - Memento stores the whole buffer (or a diff for efficiency).
// - Caretaker keeps a stack of Mementos.
// - insert(pos,ch) and erase(pos,len) modify buffer then push a new Memento.
// - undo() pops the stack and restores previous buffer.
// Full code omitted for brevity but follows the pattern shown in the main example.

