#include <iostream>
#include <vector>
using namespace std;

enum class Cell { EMPTY, X, O };

class Board {
    int n; // board dimension (n x n)
    vector<vector<Cell>> cells;
public:
    Board(int size = 3) : n(size), cells(size, vector<Cell>(size, Cell::EMPTY)) {}
    bool placeMark(int r, int c, Cell mark) {
        if (r<0||r>=n||c<0||c>=n|| cells[r][c]!=Cell::EMPTY) return false;
        cells[r][c] = mark; return true;
    }
    void display() const {
        for (auto &row: cells) {
            for (auto cell: row) {
                char ch = (cell==Cell::X)?'X':(cell==Cell::O)?'O':'_';
                cout << ch << ' ';
            }
            cout << '\n';
        }
    }
    bool checkWin(Cell mark) const {
        // rows & cols
        for (int i=0;i<n;i++) {
            bool row=true, col=true;
            for (int j=0;j<n;j++) {
                row &= (cells[i][j]==mark);
                col &= (cells[j][i]==mark);
            }
            if (row||col) return true;
        }
        // diagonals
        bool d1=true,d2=true;
        for (int i=0;i<n;i++) {
            d1 &= (cells[i][i]==mark);
            d2 &= (cells[i][n-1-i]==mark);
        }
        return d1||d2;
    }
    bool full() const {
        for (auto &row: cells)
            for (auto cell: row)
                if (cell==Cell::EMPTY) return false;
        return true;
    }
};

class Player {
    string name; Cell mark;
public:
    Player(string n, Cell m): name(move(n)), mark(m) {}
    const string& getName() const { return name; }
    Cell getMark() const { return mark; }
    void makeMove(Board &b) const {
        int r,c; 
        do {
            cout << name << " enter row and col: ";
            cin >> r >> c;
        } while (!b.placeMark(r, c, mark));
    }
};

class Game {
protected:
    Board board;
    Player p1, p2;
    Player *curr;
public:
    Game(int size, Player a, Player b) : board(size), p1(move(a)), p2(move(b)), curr(&p1) {}
    void run() {
        board.display();
        while (true) {
            curr->makeMove(board);
            board.display();
            if (board.checkWin(curr->getMark())) {
                cout << curr->getName() << " wins!\n";
                break;
            }
            if (board.full()) { cout << "Draw!\n"; break; }
            curr = (curr==&p1) ? &p2 : &p1; // swap turn
        }
    }
};

int main() {
    Player a("Alice", Cell::X), b("Bob", Cell::O);
    Game g(3, a, b);
    g.run();
    return 0;
}
// Important lines: Board encapsulates state, Game::run() is the loop, Player::makeMove() handles input.

