class SnakeLadderGame : public Game {
    vector<int> pos; // player positions
    int dice() const { return rand()%6 + 1; }
public:
    SnakeLadderGame(int size, Player a, Player b) : Game(size,a,b), pos(2,0) {}
    void processTurn() override {
        int roll = dice();
        int idx = (curr==&p1)?0:1;
        pos[idx] = min(pos[idx]+roll, size*size);
        // handle snakes/ladders map here
        cout << curr->getName() << " rolled " << roll << " now at " << pos[idx] << "\n";
    }
    bool isOver() const override { return any_of(pos.begin(), pos.end(), [&](int p){return p==size*size;}); }
};
